#include <algorithm>
#include <cassert>
#include <iostream>
#include <map>
#include <utility>
#include <vector>
using namespace std;
// 양끝 포함 구간입니다. 빈 요구는 (0,-1), 불가능은 (-1,-1)입니다.
pair<int,int> shortestCover(const vector<int>&v,const vector<int>&required){
 if(required.empty())return {0,-1};
 map<int,int>need,have;for(int x:required)++need[x];
 int missing=static_cast<int>(required.size()),left=0,bestLeft=-1,bestRight=-1;
 for(int right=0;right<static_cast<int>(v.size());++right){
  auto it=need.find(v[right]);
  if(it!=need.end()){if(have[v[right]]<it->second)--missing;++have[v[right]];}
  while(missing==0){
   if(bestLeft<0||right-left<bestRight-bestLeft){bestLeft=left;bestRight=right;}
   auto old=need.find(v[left]);
   if(old!=need.end()){--have[v[left]];if(have[v[left]]<old->second)++missing;}
   ++left;
  }
 }
 return {bestLeft,bestRight};
}
pair<int,int> reference(const vector<int>&v,const vector<int>&required){
 if(required.empty())return {0,-1};
 map<int,int>need;for(int x:required)++need[x];
 for(size_t len=1;len<=v.size();++len)for(size_t left=0;left+len<=v.size();++left){
  map<int,int>freq;for(size_t i=left;i<left+len;++i)++freq[v[i]];
  bool ok=true;for(const auto&x:need)if(freq[x.first]<x.second)ok=false;
  if(ok)return {static_cast<int>(left),static_cast<int>(left+len-1)};
 }
 return {-1,-1};
}
vector<vector<int>> arrays(int maxLength){
 vector<vector<int>>all(1),level(1);
 for(int n=1;n<=maxLength;++n){vector<vector<int>>next;
  for(const auto&v:level)for(int x:{0,1,2}){auto w=v;w.push_back(x);next.push_back(w);}
  all.insert(all.end(),next.begin(),next.end());level=next;
 }
 return all;
}
int main(){
 size_t cases=0;
 for(const auto&v:arrays(6))for(const auto&r:arrays(3)){assert(shortestCover(v,r)==reference(v,r));++cases;}
 assert(shortestCover({1,2,1,3,2,1},{1,1,2})==make_pair(0,2));
 assert(shortestCover({2,1,1,2},{1,1,2})==make_pair(0,2));
 cout<<cases<<" text/required cases + multiset tie examples passed\n";
}
